#!/usr/bin/env node
// Generates every docs HTML shell and component list (R-01). Run after adding or renaming a component:
//   npm run docs:build        (docs:check fails when a generated file is missing or out of date)
// Outputs (never edit them by hand):
//   <section>/components/<name>/<name>.html   component page   (reads <name>.md)
//   <section>/components/index.json           component list   (folders that contain <name>.md)
//   <section>/index.html                      Components List  (home page of the platform)
//   2-foundations/index.html                  Foundation List
//   2-foundations/foundation.html             foundation page  (#devices, #colors, …)
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const SECTIONS = { web: '3-web-components', tablet: '4-tablet-components', mobile: '5-mobile-components' };
const MARK = '<!-- GENERATED by npm run docs:build — do not edit -->';
const BODY = fs.readFileSync(path.join(ROOT, '_docs/component-body.html'), 'utf8');

const head = (title, rel, platform) => `<!doctype html>
${MARK}
<html lang="en" dir="ltr" data-theme="light" data-platform="${platform}">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
  <title>${title} · Biowave</title>
  <link rel="stylesheet" href="${rel}2-foundations/web/src/generated/tokens.css">
  <link rel="stylesheet" href="${rel}_docs/viewer.css">
</head>`;
const cfg = (o, rel) => `  <script>window.BIOWAVE_DOC = ${JSON.stringify(o)};</script>\n  <script src="${rel}_docs/viewer.js"></script>\n</body>\n</html>\n`;
const homeBody = '<body class="home-page">\n  <main data-home aria-live="polite"></main>\n';

export function expectedFiles() {
  const files = {};
  for (const [plat, sec] of Object.entries(SECTIONS)) {
    const dir = path.join(ROOT, sec, 'components');
    const names = fs.existsSync(dir) ? fs.readdirSync(dir, { withFileTypes: true }).filter((d) => d.isDirectory() && fs.existsSync(path.join(dir, d.name, `${d.name}.md`))).map((d) => d.name).sort() : [];
    files[`${sec}/components/index.json`] = JSON.stringify({ $description: 'Generated by npm run docs:build', components: names }, null, 2) + '\n';
    for (const name of names) {
      files[`${sec}/components/${name}/${name}.html`] = `${head(`${name} · ${plat}`, '../../../', plat)}\n<body>\n${BODY}${cfg({ page: 'component', platform: plat, component: name, root: '../../../' }, '../../../')}`;
    }
    files[`${sec}/index.html`] = `${head(`Components List · ${plat}`, '../', plat)}\n${homeBody}${cfg({ page: 'components', platform: plat, root: '../' }, '../')}`;
  }
  files['2-foundations/index.html'] = `${head('Foundation List', '../', 'web')}\n${homeBody}${cfg({ page: 'foundations', platform: 'web', root: '../' }, '../')}`;
  files['2-foundations/foundation.html'] = `${head('Foundation', '../', 'web')}\n${homeBody}${cfg({ page: 'foundation', platform: 'web', root: '../' }, '../')}`;
  return files;
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  let n = 0;
  for (const [rel, content] of Object.entries(expectedFiles())) {
    const abs = path.join(ROOT, rel);
    if (fs.existsSync(abs) && fs.readFileSync(abs, 'utf8') === content) continue;
    fs.mkdirSync(path.dirname(abs), { recursive: true });
    fs.writeFileSync(abs, content); n++;
    console.log('  wrote ' + rel);
  }
  console.log(`✓ docs:build — ${n} file(s) written`);
}
